// Optimized variants generated by scripts/optimize-photos.py from photos-src/.
// Each photo has AVIF + WebP at 400/1200/2400px long edge.
import manifest from '../assets/photos/manifest.json'

const files = import.meta.glob('/src/assets/photos/*.{avif,webp}', { eager: true, import: 'default' })

export const WIDTHS = [400, 1200, 2400]

// Each variant's pixel size comes from the manifest, as written. A variant is named
// for its long edge, but can be smaller if the script had to shrink it to fit its
// size limit, and srcset needs the real width.
export const photoByName = Object.fromEntries(
  Object.keys(manifest).map((name) => {
    const variants = Object.fromEntries(
      WIDTHS.map((w) => [
        w,
        {
          ...manifest[name].variants[w],
          avif: files[`/src/assets/photos/${name}-${w}.avif`],
          webp: files[`/src/assets/photos/${name}-${w}.webp`],
        },
      ]),
    )
    return [name, { name, variants }]
  }),
)

// Images that go through the pipeline for use elsewhere, not in Gallery
const NOT_IN_GALLERY = new Set(['njit-diploma', 'linkdup-certificate', 'portrait'])

export const galleryPhotos = Object.keys(photoByName)
  .filter((name) => !NOT_IN_GALLERY.has(name))
  .sort()
  .map((name) => photoByName[name])

export const srcSet = (photo, format, widths = WIDTHS) =>
  widths.map((w) => `${photo.variants[w][format]} ${photo.variants[w].width}w`).join(', ')

// sizes for a photo scaled to fit inside a box without cropping (the Lightbox): the
// width it's actually drawn at, in CSS px. A tall photo in a wide box
// is drawn by its height, far narrower than the box, so the box width alone would
// fetch a much bigger file than it needs.
export const containSizes = (photo, boxWidth, boxHeight) => {
  const { width, height } = photo.variants[WIDTHS[0]]
  return `${Math.ceil(Math.min(boxWidth, boxHeight * (width / height)))}px`
}

// Approved descriptions, by photo file: the alt text wherever the photo appears (Hero,
// About, the Gallery reel and its Lightbox).
export const photoAlt = {
  city: 'The Brooklyn Bridge with the Lower Manhattan skyline at sunset.',
  friends: 'Two friends seen from behind at a railing at night, one in a green and gold varsity jacket.',
  nature: 'Looking up through a canopy of tall pine trees.',
  portrait: 'Portrait of Israel Alcántara.',
  streetwear: 'Israel standing on a grassy coastal hillside.',
}
